// ==========================================================================
// Shared CRUD utility — toast, modal open/close, delete-confirm modal
// ==========================================================================
window.MC = window.MC || {};

MC.toast = function (msg, type = "success") {
    const icons = { success: "✓", error: "✕", info: "ℹ" };
    const el = document.createElement("div");
    el.className = `mc-toast ${type}`;
    el.innerHTML = `<span>${icons[type] || ""}</span> ${msg}`;
    document.body.appendChild(el);
    setTimeout(() => {
        el.style.opacity = "0";
        el.style.transition = "opacity 0.3s";
        setTimeout(() => el.remove(), 300);
    }, 2800);
};

MC.openModal = function (id) {
    const el = document.getElementById(id);
    if (!el) return;
    // Preline-native overlays (class="hs-overlay ...") open through Preline's
    // own engine so its show/hide transitions, focus trap and Esc handling
    // stay in charge; the legacy .modal-overlay markup keeps its plain
    // class-toggle behavior.
    if (el.classList.contains("hs-overlay") && window.HSOverlay) {
        window.HSOverlay.open(el);
        return;
    }
    el.classList.remove("hidden");
    document.body.style.overflow = "hidden";
};

MC.closeModal = function (id) {
    const el = document.getElementById(id);
    if (!el) return;
    if (el.classList.contains("hs-overlay") && window.HSOverlay) {
        window.HSOverlay.close(el);
        return;
    }
    el.classList.add("hidden");
    document.body.style.overflow = "";
};

MC.confirmDelete = function (name, onConfirm) {
    document.getElementById("del-name").textContent = name;
    MC._delCallback = onConfirm;
    MC.openModal("del-modal");
};

MC.initDeleteModal = function () {
    const btn = document.getElementById("del-confirm-btn");
    if (btn)
        btn.onclick = () => {
            if (MC._delCallback) MC._delCallback();
            MC.closeModal("del-modal");
        };
    const cancel = document.getElementById("del-cancel-btn");
    if (cancel) cancel.onclick = () => MC.closeModal("del-modal");
};

MC.closeOnBackdrop = function (id) {
    const el = document.getElementById(id);
    if (el)
        el.addEventListener("mousedown", (e) => {
            if (e.target === el) MC.closeModal(id);
        });
};

// Shared delete confirm modal HTML — inject into any page
MC.deleteModalHTML = `
<div id="del-modal" class="modal-overlay hidden">
  <div class="modal-panel sm">
    <div class="flex items-center gap-3">
      <div class="w-11 h-11 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center shrink-0">
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="text-red-600"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6M14 11v6"/><path d="M9 6V4h6v2"/></svg>
      </div>
      <div><h3 class="font-bold text-gray-900 text-lg">Delete Record</h3><p class="text-sm text-gray-500 dark:text-gray-400">This action cannot be undone.</p></div>
    </div>
    <p class="text-sm text-gray-600 dark:text-gray-300 mt-4 mb-6">Are you sure you want to delete <strong id="del-name" class="text-gray-900"></strong>?</p>
    <div class="flex gap-3 justify-end">
      <button id="del-cancel-btn" class="px-4 py-2 rounded-lg border border-gray-200 dark:border-slate-600 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-slate-700">Cancel</button>
      <button id="del-confirm-btn" class="px-4 py-2 rounded-lg bg-red-600 hover:bg-red-700 text-white text-sm font-medium">Delete</button>
    </div>
  </div>
</div>`;

// ==========================================================================
// Shared CRUD List engine — MC.crudList: search/filter/add/edit/delete
// plumbing for a simple in-memory table page (search box, 0-N <select>
// filters, add/edit modal, delete-confirm modal, live stat tiles). Call once
// per page, already gated by document.body.dataset.page, passing the
// page-specific data + the bits that differ per page (row markup, stat
// calculations, form fill/build). See blood-requests, blood-camps, etc. for
// usage.
// ==========================================================================
MC.crudList = function (cfg) {
    const $ = (id) => document.getElementById(id);
    let data = cfg.data;
    let nextId = cfg.nextId;
    let editingId = null;
    const filters = cfg.filters || [];

    function render() {
        const q = $("search").value.toLowerCase();
        const filterVals = filters.map((f) => $(f.id).value);
        const rows = data.filter((r) => {
            const m = !q || cfg.searchFields.some((f) => String(r[f]).toLowerCase().includes(q));
            return m && filters.every((f, i) => !filterVals[i] || r[f.field] === filterVals[i]);
        });
        const visible = new Set(rows.map((r) => r.id));
        $("tbody").querySelectorAll("[data-row-id]").forEach((tr) => {
            tr.classList.toggle("hidden", !visible.has(Number(tr.dataset.rowId)));
        });
        const emptyRow = $("tbody-empty");
        if (emptyRow) emptyRow.classList.toggle("hidden", rows.length !== 0);
        $("count").textContent = rows.length + " of " + data.length;
        cfg.updateStats($, data);
    }

    window[cfg.prefix + "OpenAdd"] = function () {
        editingId = null;
        $("m-title").textContent = cfg.addTitle;
        $("btn-save").textContent = cfg.addSaveLabel;
        $("m-form").reset();
        if (cfg.onOpenAdd) cfg.onOpenAdd($);
        MC.openModal("form-modal");
    };
    window[cfg.prefix + "OpenEdit"] = function (id) {
        const r = data.find((x) => x.id === id);
        if (!r) return;
        editingId = id;
        $("m-title").textContent = cfg.editTitle;
        $("btn-save").textContent = "Update";
        cfg.fillForm($, r);
        MC.openModal("form-modal");
    };
    window[cfg.deleteFnName || (cfg.prefix + "Delete")] = function (id, name) {
        MC.confirmDelete(name, () => {
            data = data.filter((x) => x.id !== id);
            const el = $("tbody").querySelector(`[data-row-id="${id}"]`);
            if (el) el.remove();
            render();
            MC.toast(cfg.deleteToast, "success");
        });
    };

    $("btn-add").onclick = window[cfg.prefix + "OpenAdd"];
    $("btn-save").onclick = function () {
        const rec = cfg.buildRecord($);
        if (!rec) return;
        if (editingId) {
            const idx = data.findIndex((x) => x.id === editingId);
            data[idx] = Object.assign({}, data[idx], rec);
            const el = $("tbody").querySelector(`[data-row-id="${editingId}"]`);
            if (el) el.outerHTML = cfg.rowHTML(data[idx]);
            MC.toast(cfg.editToast, "success");
        } else {
            const newRec = Object.assign({ id: nextId++ }, rec);
            data.push(newRec);
            $("tbody").insertAdjacentHTML("beforeend", cfg.rowHTML(newRec));
            MC.toast(cfg.addToast, "success");
        }
        MC.closeModal("form-modal");
        render();
    };
    const closeBtn = $("m-close");
    if (closeBtn) closeBtn.onclick = () => MC.closeModal("form-modal");
    const cancelBtn = $("m-cancel");
    if (cancelBtn) cancelBtn.onclick = () => MC.closeModal("form-modal");
    $("search").addEventListener("input", render);
    filters.forEach((f) => $(f.id).addEventListener("change", render));
    MC.initDeleteModal();
    MC.closeOnBackdrop("form-modal");
    MC.closeOnBackdrop("del-modal");
    cfg.updateStats($, data);
};

// ==========================================================================
// Shared Grid JS — MC.grid: search, filters, pagination, bulk selection
// ==========================================================================
MC.grid = function (cfg) {
    if (!cfg || !cfg.tbody) return null;

    const key = cfg.rowKey || ((r) => r.id);
    const state = {
        rows: (cfg.data || []).slice(),
        page: 1,
        perPage: cfg.pageSize || 10,
        selected: new Set(),
    };

    function filtered() {
        const term = cfg.search ? cfg.search.value.trim().toLowerCase() : "";
        return state.rows.filter(function (row) {
            if (term && !Object.values(row).join(" ").toLowerCase().includes(term)) {
                return false;
            }
            return (cfg.filters || []).every(function (f) {
                const v = f.el ? f.el.value : "";
                return !v || f.match(row, v);
            });
        });
    }

    function syncBulk() {
        if (cfg.bulkBar) cfg.bulkBar.classList.toggle("hidden", state.selected.size === 0);
        if (cfg.bulkCount) cfg.bulkCount.textContent = state.selected.size;
    }

    function syncSelectAll() {
        if (!cfg.selectAll) return;
        const boxes = Array.from(cfg.tbody.querySelectorAll("[data-row-select]"));
        const checked = boxes.filter((b) => b.checked).length;
        cfg.selectAll.checked = boxes.length > 0 && checked === boxes.length;
        cfg.selectAll.indeterminate = checked > 0 && checked < boxes.length;
    }

    function renderEmpty(colspan) {
        const e = cfg.empty || {};
        const tr = document.createElement("tr");
        tr.innerHTML =
            '<td colspan="' + colspan + '" class="py-12 text-center">' +
            '<div class="flex flex-col items-center gap-2">' +
            '<span class="w-12 h-12 rounded-xl bg-gray-100 dark:bg-slate-800 flex items-center justify-center">' +
            '<i class="' + (e.icon || "icon-inbox") + ' text-xl text-gray-400"></i>' +
            "</span>" +
            '<p class="text-sm font-semibold text-gray-900">' + (e.title || "No records found") + "</p>" +
            '<p class="text-xs text-gray-500 dark:text-gray-400">' + (e.text || "Try adjusting your search or filters.") + "</p>" +
            "</div></td>";
        cfg.tbody.appendChild(tr);
    }

    function pageButton(label, target, opts) {
        const o = opts || {};
        const b = document.createElement("button");
        b.type = "button";
        b.className = o.active
            ? "min-w-9 h-9 px-2 rounded-lg text-sm font-semibold bg-primary text-white"
            : "min-w-9 h-9 px-2 rounded-lg text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors disabled:opacity-40 disabled:pointer-events-none";
        b.disabled = !!o.disabled;
        if (o.ariaLabel) b.setAttribute("aria-label", o.ariaLabel);
        if (o.active) b.setAttribute("aria-current", "page");
        if (o.icon) {
            const i = document.createElement("i");
            i.className = o.icon + " text-sm";
            b.appendChild(i);
        } else {
            b.textContent = label;
        }
        b.addEventListener("click", function () {
            state.page = target;
            render();
        });
        return b;
    }

    function renderPager(pages) {
        if (!cfg.pager) return;
        cfg.pager.textContent = "";
        cfg.pager.appendChild(
            pageButton("", state.page - 1, {
                icon: "icon-chevron-left",
                disabled: state.page === 1,
                ariaLabel: "Previous page",
            }),
        );
        let start = Math.max(1, state.page - 2);
        let end = Math.min(pages, start + 4);
        start = Math.max(1, end - 4);
        for (let p = start; p <= end; p++) {
            cfg.pager.appendChild(pageButton(String(p), p, { active: p === state.page }));
        }
        cfg.pager.appendChild(
            pageButton("", state.page + 1, {
                icon: "icon-chevron-right",
                disabled: state.page === pages,
                ariaLabel: "Next page",
            }),
        );
    }

    function renderMeta(total, from, pages) {
        if (cfg.info) {
            cfg.info.textContent = total
                ? "Showing " + (from + 1) + " to " + Math.min(from + state.perPage, total) + " of " + total + " entries"
                : "Showing 0 to 0 of 0 entries";
        }

        renderPager(pages);
        syncSelectAll();
        syncBulk();
    }

    function render() {
        const rows = filtered();
        const total = rows.length;
        const pages = Math.max(1, Math.ceil(total / state.perPage));
        if (state.page > pages) state.page = pages;

        const from = (state.page - 1) * state.perPage;
        const slice = rows.slice(from, from + state.perPage);
        const colspan = cfg.columns.length + (cfg.selectAll ? 1 : 0);

        cfg.tbody.textContent = "";

        if (total === 0) {
            renderEmpty(colspan);
        } else {
            slice.forEach(function (row) {
                const tr = document.createElement("tr");
                let html = "";
                if (cfg.selectAll) {
                    const id = String(key(row));
                    html +=
                        '<td><input type="checkbox" data-row-select value="' + id +
                        '" aria-label="Select row"' + (state.selected.has(id) ? " checked" : "") +
                        ' class="w-4 h-4 rounded border-gray-300 text-primary focus:ring-primary"></td>';
                }
                cfg.columns.forEach(function (c) {
                    html += "<td" + (c.cls ? ' class="' + c.cls + '"' : "") + ">" + c.render(row) + "</td>";
                });
                tr.innerHTML = html;
                cfg.tbody.appendChild(tr);
            });
        }

        renderMeta(total, from, pages);

        // Preline dropdowns inside freshly rendered rows need re-initialising.
        if (window.HSStaticMethods) window.HSStaticMethods.autoInit();
    }

    if (cfg.search) {
        cfg.search.addEventListener("input", function () {
            state.page = 1;
            render();
        });
    }

    (cfg.filters || []).forEach(function (f) {
        if (f.el) {
            f.el.addEventListener("change", function () {
                state.page = 1;
                render();
            });
        }
    });

    if (cfg.selectAll) {
        cfg.selectAll.addEventListener("change", function () {
            cfg.tbody.querySelectorAll("[data-row-select]").forEach(function (b) {
                b.checked = cfg.selectAll.checked;
                if (b.checked) state.selected.add(b.value);
                else state.selected.delete(b.value);
            });
            syncBulk();
        });
    }

    cfg.tbody.addEventListener("change", function (e) {
        const box = e.target.closest("[data-row-select]");
        if (!box) return;
        if (box.checked) state.selected.add(box.value);
        else state.selected.delete(box.value);
        syncSelectAll();
        syncBulk();
    });

    if (cfg.skipInitialRender) {
        // The tbody already ships with static, server-rendered rows for the
        // default state (page 1, no search/filter/sort). Wire up the pager,
        // bulk bar and selection state to match without touching the DOM
        // rows themselves. Any later interaction (search/filter/page/select)
        // goes through the normal render() path and rebuilds rows as usual.
        const rows = filtered();
        const total = rows.length;
        const pages = Math.max(1, Math.ceil(total / state.perPage));
        const from = (state.page - 1) * state.perPage;
        renderMeta(total, from, pages);
    } else {
        render();
    }

    return {
        refresh: render,
        selected: function () {
            return Array.from(state.selected);
        },
        clearSelection: function () {
            state.selected.clear();
            render();
        },
        data: function () {
            return state.rows;
        },
        setData: function (d) {
            state.rows = d.slice();
            state.page = 1;
            render();
        },
    };
};

// Maps a status value to a .badge class from the existing design system.
MC.badge = function (map, value) {
    return '<span class="badge ' + (map[value] || "badge-gray") + '">' + value + "</span>";
};

// Row action dropdown (Preline). items: [{label, icon, danger, act}]
MC.actions = function (id, items) {
    let html =
        '<div class="hs-dropdown relative inline-flex [--placement:bottom-right]">' +
        '<button type="button" aria-label="Row actions" class="hs-dropdown-toggle p-2 rounded-lg text-gray-500 hover:text-primary hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors">' +
        '<i class="icon-ellipsis-vertical text-sm"></i></button>' +
        '<div class="hs-dropdown-menu transition-[opacity,margin] duration-150 hs-dropdown-open:opacity-100 opacity-0 hidden z-50 min-w-44 bg-white dark:bg-slate-800 shadow-lg rounded-lg p-1 border border-border-color" role="menu">';
    items.forEach(function (it) {
        html +=
            '<button type="button" role="menuitem" data-act="' + it.act + '" data-id="' + id + '" ' +
            'class="w-full flex items-center gap-2.5 py-2 px-3 rounded-lg text-sm ' +
            (it.danger
                ? "text-danger hover:bg-danger/10"
                : "text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-slate-700") +
            '"><i class="' + it.icon + ' text-sm"></i>' + it.label + "</button>";
    });
    return html + "</div></div>";
};

// ==========================================================================
// Shared Static List/Grid — MC.staticList: search, attribute filters, sort
// and pagination against markup that already contains every record (as
// static cards and/or table rows). Unlike MC.grid, this never creates HTML:
// filtering/pagination only toggle `hidden`, sorting only reorders existing
// nodes (appendChild), and pager buttons are plain UI chrome, not content.
// Multiple synchronized views (e.g. a card grid + a list table showing the
// same records) share one state by running the same predicate/comparator
// independently against each view's own elements.
// ==========================================================================
MC.staticList = function (cfg) {
    if (!cfg || !cfg.views || !cfg.views.length) return null;

    var state = { page: 1, perPage: cfg.pageSize || Infinity };

    function itemsOf(view) {
        return Array.prototype.slice.call(view.container.querySelectorAll(view.itemSelector));
    }

    function passes(el) {
        var term = cfg.search ? cfg.search.value.trim().toLowerCase() : "";
        if (term && (el.textContent || "").toLowerCase().indexOf(term) === -1) return false;
        return cfg.matches ? cfg.matches(el) : true;
    }

    function pageButton(label, target, opts) {
        var o = opts || {};
        var b = document.createElement("button");
        b.type = "button";
        b.className = o.active
            ? "pm-page-btn is-active"
            : "pm-page-btn";
        b.disabled = !!o.disabled;
        if (o.ariaLabel) b.setAttribute("aria-label", o.ariaLabel);
        if (o.icon) {
            var i = document.createElement("i");
            i.className = o.icon;
            b.appendChild(i);
        } else {
            b.textContent = label;
        }
        b.addEventListener("click", function () {
            state.page = target;
            render();
        });
        return b;
    }

    function renderPager(pages) {
        if (!cfg.pager) return;
        cfg.pager.textContent = "";
        cfg.pager.appendChild(pageButton("", state.page - 1, { icon: "icon-chevron-left", disabled: state.page === 1, ariaLabel: "Previous page" }));
        var start = Math.max(1, state.page - 2), end = Math.min(pages, start + 4);
        start = Math.max(1, end - 4);
        for (var p = start; p <= end; p++) cfg.pager.appendChild(pageButton(String(p), p, { active: p === state.page }));
        cfg.pager.appendChild(pageButton("", state.page + 1, { icon: "icon-chevron-right", disabled: state.page === pages, ariaLabel: "Next page" }));
    }

    function render() {
        var info = null;
        cfg.views.forEach(function (view) {
            var all = itemsOf(view);
            var shown = all.filter(passes);
            if (cfg.compare) shown = shown.slice().sort(cfg.compare);
            var pages = Math.max(1, Math.ceil(shown.length / state.perPage));
            if (state.page > pages) state.page = pages;
            // (page-1) * Infinity is NaN when perPage is unset (no pager on
            // the page) — guard it explicitly rather than relying on callers
            // to pass a large finite pageSize as a workaround.
            var start = state.perPage === Infinity ? 0 : (state.page - 1) * state.perPage;
            var slice = state.perPage === Infinity ? shown.slice() : shown.slice(start, start + state.perPage);
            all.forEach(function (el) { el.hidden = slice.indexOf(el) === -1; });
            slice.forEach(function (el) { view.container.appendChild(el); });
            if (!info) info = { total: shown.length, allCount: all.length, from: start, shown: slice.length, pages: pages };
        });
        if (window.HSStaticMethods) window.HSStaticMethods.autoInit();
        if (cfg.onRender) cfg.onRender(info);
        renderPager(info.pages);
        return info;
    }

    if (cfg.search) cfg.search.addEventListener("input", function () { state.page = 1; render(); });
    (cfg.filterEls || []).forEach(function (el) { el.addEventListener("change", function () { state.page = 1; render(); }); });
    if (cfg.sortEl) cfg.sortEl.addEventListener("change", render);

    render();

    return {
        refresh: render,
        setPage: function (p) { state.page = p; render(); },
        setPerPage: function (n) { state.perPage = n; state.page = 1; render(); },
        state: state,
    };
};

// Toggle a class on click without generating any markup — used for
// favorite/pin style indicators that only need a visual on/off state.
(function () {
    "use strict";
    document.addEventListener("click", function (e) {
        var fav = e.target.closest("[data-fav-toggle]");
        if (fav) { e.stopPropagation(); fav.classList.toggle("on"); return; }
        var pin = e.target.closest("[data-pin-toggle]");
        if (pin) { e.stopPropagation(); pin.classList.toggle("is-pinned"); return; }
        if (e.target.closest("[data-print-trigger]")) { e.stopPropagation(); window.print(); return; }
        var del = e.target.closest("[data-remove-item]");
        if (del) {
            e.stopPropagation();
            var item = document.getElementById(del.getAttribute("data-remove-item"));
            if (!item) return;
            var nameEl = item.querySelector("[data-name-text]");
            var name = nameEl ? nameEl.textContent.trim() : "this record";
            if (window.MC && MC.confirmDelete) {
                MC.confirmDelete(name, function () {
                    document.querySelectorAll('[id$="-item-' + item.getAttribute("data-id") + '"]').forEach(function (el) { el.remove(); });
                });
            } else {
                item.remove();
            }
        }
    });
    // Column-visibility dropdowns: any [data-col-toggle] checkbox inside a
    // [data-cols-menu] shows/hides every element sharing its [data-col].
    document.addEventListener("change", function (e) {
        var col = e.target.closest("[data-col-toggle]");
        if (col) {
            document.querySelectorAll('[data-col="' + col.getAttribute("data-col-toggle") + '"]').forEach(function (el) {
                el.style.display = col.checked ? "" : "none";
            });
            return;
        }
        // Bulk selection: a [data-row-select="id"] checkbox may exist once per
        // synchronized view (e.g. a grid card and its matching table row) —
        // keep every copy in sync and refresh any [data-bulk-bar] count.
        var box = e.target.closest("[data-row-select]");
        if (!box) return;
        var id = box.getAttribute("data-row-select");
        document.querySelectorAll('[data-row-select="' + id + '"]').forEach(function (b) { b.checked = box.checked; });
        var ids = new Set();
        document.querySelectorAll("[data-row-select]:checked").forEach(function (b) { ids.add(b.getAttribute("data-row-select")); });
        document.querySelectorAll("[data-bulk-bar]").forEach(function (bar) {
            bar.hidden = ids.size === 0;
            var count = bar.querySelector("[data-bulk-count]");
            if (count) count.textContent = ids.size;
        });
    });

    document.addEventListener("click", function (e) {
        if (e.target.closest("[data-clear-selection]")) {
            document.querySelectorAll("[data-row-select]:checked").forEach(function (b) { b.checked = false; });
            document.querySelectorAll("[data-bulk-bar]").forEach(function (bar) { bar.hidden = true; });
            return;
        }
        var rm = e.target.closest("[data-remove-selected]");
        if (rm) {
            var ids = new Set();
            document.querySelectorAll("[data-row-select]:checked").forEach(function (b) { ids.add(b.getAttribute("data-row-select")); });
            ids.forEach(function (id) {
                document.querySelectorAll('[id$="-item-' + id + '"]').forEach(function (el) { el.remove(); });
            });
            document.querySelectorAll("[data-bulk-bar]").forEach(function (bar) { bar.hidden = true; });
        }
    });
})();

// ==========================================================================
// Appointment Statistics Card — MC.apptStats (Appointment module only)
// ==========================================================================
(function () {
    "use strict";

    const W = 80;
    const H = 24;

    function sparkline(series) {
        if (!series || series.length < 2) return "";

        const max = Math.max.apply(null, series);
        const min = Math.min.apply(null, series);
        const span = max - min || 1;
        const step = W / (series.length - 1);

        const points = series.map(function (v, i) {
            const x = (i * step).toFixed(1);
            const y = (H - 2 - ((v - min) / span) * (H - 4)).toFixed(1);
            return x + "," + y;
        });

        const area = "0," + H + " " + points.join(" ") + " " + W + "," + H;
        const last = points[points.length - 1].split(",");

        return (
            '<svg class="appt-stat-spark" viewBox="0 0 ' + W + " " + H + '" preserveAspectRatio="none" aria-hidden="true" focusable="false">' +
            '<polygon points="' + area + '" fill="currentColor" opacity="0.12"></polygon>' +
            '<polyline points="' + points.join(" ") + '" fill="none" stroke="currentColor" stroke-width="1.5" ' +
            'stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"></polyline>' +
            '<circle cx="' + last[0] + '" cy="' + last[1] + '" r="1.8" fill="currentColor"></circle>' +
            "</svg>"
        );
    }

    function delta(value) {
        if (value === null || value === undefined) return "";
        const up = value > 0;
        const flat = value === 0;
        const cls = flat ? "is-flat" : up ? "is-up" : "is-down";
        const icon = flat ? "icon-minus" : up ? "icon-trending-up" : "icon-trending-down";
        const sign = up ? "+" : "";
        const label = flat ? "No change" : sign + value + "% " + (up ? "increase" : "decrease");
        return (
            '<span class="appt-stat-delta ' + cls + '" title="' + label + '">' +
            '<i class="' + icon + ' text-[10px]" aria-hidden="true"></i>' +
            '<span class="sr-only">' + label + "</span>" +
            '<span aria-hidden="true">' + sign + value + "%</span></span>"
        );
    }

    MC.apptStat = function (cfg) {
        return (
            '<article class="appt-stat tone-' + (cfg.tone || "primary") + '">' +
            '<div class="appt-stat-head">' +
            '<span class="appt-stat-icon"><i class="' + cfg.icon + '" aria-hidden="true"></i></span>' +
            delta(cfg.delta) +
            "</div>" +
            '<p class="appt-stat-value" id="' + cfg.id + '">0</p>' +
            '<p class="appt-stat-label">' + cfg.label + "</p>" +
            '<div class="appt-stat-foot">' +
            sparkline(cfg.spark) +
            '<span class="appt-stat-meta">' + (cfg.meta || "vs last week") + "</span>" +
            "</div></article>"
        );
    };

    MC.apptStats = function (container, list) {
        if (!container) return;
        container.innerHTML = list.map(MC.apptStat).join("");
    };
})();

// ==========================================================================
// Emergency KPI Card — MC.erKpis (Emergency module only)
// ==========================================================================
(function () {
    "use strict";

    const ECG_POINTS =
        "0,10 14,10 18,10 22,7 26,13 30,10 36,10 40,2 44,18 48,10 58,10 " +
        "62,8 66,12 70,10 82,10 86,9 90,11 94,10 100,10";

    function ecg() {
        return (
            '<svg class="er-kpi-ecg" viewBox="0 0 100 20" preserveAspectRatio="none" aria-hidden="true" focusable="false">' +
            '<polyline class="er-kpi-ecg-line" points="' + ECG_POINTS + '" fill="none" stroke="currentColor" ' +
            'stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"></polyline>' +
            "</svg>"
        );
    }

    function meter(pct) {
        const value = Math.max(0, Math.min(100, pct));
        return (
            '<svg class="er-kpi-meter" viewBox="0 0 100 4" preserveAspectRatio="none" role="img" ' +
            'aria-label="Capacity ' + value + ' percent">' +
            '<rect class="er-kpi-meter-track" x="0" y="0" width="100" height="4" rx="2" fill="currentColor" opacity="0.9"></rect>' +
            '<rect x="0" y="0" width="' + value + '" height="4" rx="2" fill="currentColor"></rect>' +
            "</svg>"
        );
    }

    MC.erKpi = function (cfg) {
        const hasMeter = cfg.pct !== null && cfg.pct !== undefined;

        const live = cfg.live
            ? '<span class="er-kpi-live"><span class="er-kpi-live-dot" aria-hidden="true"></span>' + cfg.live + "</span>"
            : "";

        const unit = cfg.unit ? '<span class="er-kpi-unit">' + cfg.unit + "</span>" : "";

        const foot = hasMeter
            ? meter(cfg.pct) +
              '<div class="er-kpi-foot"><span class="er-kpi-meta">' + (cfg.meta || "") + "</span>" +
              '<span class="er-kpi-pct">' + cfg.pct + "%</span></div>"
            : '<div class="er-kpi-foot"><span class="er-kpi-meta">' + (cfg.meta || "") + "</span></div>";

        return (
            '<article class="er-kpi tone-' + (cfg.tone || "critical") + '">' +
            '<div class="er-kpi-head">' +
            '<span class="er-kpi-icon"><i class="' + cfg.icon + '" aria-hidden="true"></i></span>' +
            live +
            "</div>" +
            '<p class="er-kpi-value"><span id="' + cfg.id + '">0</span>' + unit + "</p>" +
            '<p class="er-kpi-label">' + cfg.label + "</p>" +
            (cfg.ecg ? ecg() : "") +
            foot +
            "</article>"
        );
    };

    MC.erKpis = function (container, list) {
        if (!container) return;
        container.innerHTML = list.map(MC.erKpi).join("");
    };
})();

// ==========================================================================
// Sidebar toggle, page-action delegation (main.js core)
// ==========================================================================
(function () {
    "use strict";

    var wrapper = document.querySelector(".main-wrapper");
    var overlay = document.createElement("div");
    overlay.className = "sidebar-overlay";
    if (wrapper && wrapper.parentNode) {
        wrapper.parentNode.insertBefore(overlay, wrapper);
    }

    // Toggle Mobile Menu (#menu_btn, #mobile_btn) - vanilla JS wrapper
    document.addEventListener("click", function (e) {
        const menuBtn =
            e.target.closest("#menu_btn") || e.target.closest("#mobile_btn");
        const sidebarClose = e.target.closest(".sidebar-close");
        const sidebarOverlayClick = e.target.closest(".sidebar-overlay");

        // Cached elements
        const wrapperEl = document.querySelector(".main-wrapper");
        const overlayEl = document.querySelector(".sidebar-overlay");
        const htmlEl = document.documentElement;

        if (menuBtn) {
            e.preventDefault();
            if (wrapperEl) wrapperEl.classList.toggle("slide-nav");
            if (overlayEl) overlayEl.classList.toggle("opened");
            htmlEl.classList.toggle("menu-opened");
        }

        if (sidebarClose || sidebarOverlayClick) {
            if (wrapperEl) wrapperEl.classList.remove("slide-nav");
            if (overlayEl) overlayEl.classList.remove("opened");
            htmlEl.classList.remove("menu-opened");
        }
    });

    // Shared page-action delegation (replaces repeated inline onclick="..." handlers)
    document.addEventListener("click", function (e) {
        const printBtn = e.target.closest('[data-action="print"]');
        if (printBtn) {
            window.print();
            return;
        }

        const reloadBtn = e.target.closest('[data-action="reload"]');
        if (reloadBtn) {
            location.reload();
            return;
        }

        const navBtn = e.target.closest("[data-href]");
        if (navBtn) {
            location.href = navBtn.getAttribute("data-href");
        }
    });

    // Shared no-op submit guard (replaces repeated inline onsubmit="return false;")
    document.addEventListener("submit", function (e) {
        if (e.target.matches("[data-noop-submit]")) {
            e.preventDefault();
        }
    });

    document.addEventListener("DOMContentLoaded", function () {
        const closeBtn = document.getElementById("close-notification");
        const dropdownParent = document.getElementById("notification-dropdown");

        if (closeBtn && dropdownParent) {
            closeBtn.addEventListener("click", function () {
                if (window.HSDropdown) {
                    window.HSDropdown.close(dropdownParent);
                }
            });
        }
    });

    // Global password visibility toggle
    document.addEventListener("click", function (e) {
		const btn = e.target.closest("button");
		if (!btn) return;

		// 1. Fixed: Look for your font icon classes instead of SVG elements
		const eyeIcon = btn.querySelector(".icon-eye-off, .icon-eye");
		if (!eyeIcon) return;

		const container = btn.closest(".relative");
		if (!container) return;

		const input = container.querySelector("input");
		if (!input) return;

		if (
			input.type === "password" ||
			input.dataset.passwordToggle === "true"
		) {
			input.dataset.passwordToggle = "true";
			const isPassword = input.type === "password";
			input.type = isPassword ? "text" : "password";

			// 2. Toggles the classes cleanly on your font icon
			btn.innerHTML = isPassword
				? '<i class="icon-eye text-base "></i>'
				: '<i class="icon-eye-off text-base"></i>';
		}
	});

    // Initialize Flatpickr on elements with data-provider="flatpickr"
	if (typeof flatpickr === "undefined") {
		console.warn("[script.js] flatpickr library not loaded on this page; skipping date-picker init.");
	} else {
	document.querySelectorAll('[data-provider="flatpickr"]').forEach((el) => {
		const config = {
			disableMobile: true,
		};

		// --- 1. Handle Wrap Mode ---
		if (el.getAttribute("data-wrap") === "true") {
			config.wrap = true;

			// Crucial: This manually updates the <span> text
			config.onChange = function(selectedDates, dateStr, instance) {
				// Find the span INSIDE the current picker container
				const displaySpan = instance.element.querySelector('[data-input-span]');
				if (displaySpan) {
					displaySpan.textContent = dateStr;
				}
			};
		}

		if (el.hasAttribute("data-date-format")) {
			config.dateFormat = el.getAttribute("data-date-format");
		}
		if (el.hasAttribute("data-enable-time")) {
			config.enableTime = true;
			config.dateFormat = config.dateFormat ?
				`${config.dateFormat} H:i` :
				"Y-m-d H:i";
		}
		if (el.hasAttribute("data-altFormat")) {
			config.altInput = true;
			config.altFormat = el.getAttribute("data-altFormat");
		}
		if (el.hasAttribute("data-minDate")) {
			config.minDate = el.getAttribute("data-minDate");
		}
		if (el.hasAttribute("data-maxDate")) {
			config.maxDate = el.getAttribute("data-maxDate");
		}
		if (el.hasAttribute("data-default-date")) {
			const defaultDate = el.getAttribute("data-default-date");
			// Check if it's a valid date string
			if (
				!["true", "false", "", null].includes(defaultDate) &&
				!isNaN(Date.parse(defaultDate))
			) {
				config.defaultDate = defaultDate;
			}
		}
		if (el.hasAttribute("data-multiple-date")) {
			config.mode = "multiple";
		}
		if (el.hasAttribute("data-range-date")) {
			config.mode = "range";
		}
		if (el.hasAttribute("data-inline-date")) {
			config.inline = true;
			const inlineDate = el.getAttribute("data-inline-date");
			if (
				!["true", "false", "", null].includes(inlineDate) &&
				!isNaN(Date.parse(inlineDate))
			) {
				config.defaultDate = inlineDate;
			}
		}
		if (el.hasAttribute("data-disable-date")) {
			config.disable = el.getAttribute("data-disable-date").split(",");
		}
		if (el.hasAttribute("data-week-number")) {
			config.weekNumbers = true;
		}
		flatpickr(el, config);
	});
	}

    // Time Picker
	if (typeof flatpickr !== "undefined") {
	document.querySelectorAll('[data-provider="timepickr"]').forEach((item) => {
		const attrs = item.attributes;
		const config = {
			enableTime: true,
			noCalendar: true,
			dateFormat: "H:i",
		};

		if (attrs["data-time-hrs"]) {
			config.time_24hr = true;
		}

		if (attrs["data-min-time"]) {
			config.minTime = attrs["data-min-time"].value;
		}

		if (attrs["data-max-time"]) {
			config.maxTime = attrs["data-max-time"].value;
		}

		if (attrs["data-default-time"]) {
			config.defaultDate = attrs["data-default-time"].value;
		}

		if (attrs["data-time-inline"]) {
			config.inline = true;
			config.defaultDate = attrs["data-time-inline"].value;
		}

		flatpickr(item, config);
	});
	}

	// Sidebar Active
	window.addEventListener('load', () => {
		setTimeout(() => {
			const activeItem = document.querySelector('#sidebar-menu .active');
			const scrollElement = document.querySelector('.sidebar-inner .simplebar-mask')?.querySelector('.simplebar-content-wrapper');

			if (activeItem && scrollElement) {
				// Get positions relative to the screen viewport
				const activeRect = activeItem.getBoundingClientRect();
				const scrollRect = scrollElement.getBoundingClientRect();

				// Calculate the precise scroll position inside the container
				const targetScrollTop = scrollElement.scrollTop + (activeRect.top - scrollRect.top) - 100;

				// Smoothly scroll to the item
				scrollElement.scrollTo({
					top: targetScrollTop,
					behavior: 'smooth'
				});
			}
		}, 500);
	});

// Inside your assets/js/script.js
document.addEventListener('DOMContentLoaded', () => {
  if (typeof AOS !== 'undefined') {
    AOS.init({
      duration: 800,
      once: true
    });

    // AOS positions elements using window scroll offsets, but the app shell
    // scrolls inside <main> (see body:has(.sidebar) in style.css) while
    // window never moves — so AOS's own reveal-on-scroll math never fires
    // for anything below the first screen. Drive the reveal ourselves with
    // an IntersectionObserver scoped to main.
    const scrollEl = document.querySelector('main');
    const aosTargets = document.querySelectorAll('[data-aos]');
    if (scrollEl && aosTargets.length) {
      const io = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.classList.add('aos-animate');
          io.unobserve(entry.target);
        });
      }, { root: scrollEl, threshold: 0 });
      aosTargets.forEach((el) => io.observe(el));
    }
  } else {
    console.error("Local aos.js file was not found or failed to load.");
  }
});

})();

// UI Kit: "Show Code" toggle and "Copy" button handling
document.addEventListener("DOMContentLoaded", function () {
  document.addEventListener("click", function (e) {
    var toggleBtn = e.target.closest('[data-toggle="code"]');
    if (toggleBtn) {
      // Find the nearest following sibling with class "code", collecting the
      // preview/design elements in between so they can be hidden while the code shows.
      var container = toggleBtn.closest("div");
      var target = container ? container.nextElementSibling : null;
      var previewEls = [];
      while (target && !target.classList.contains("code")) {
        previewEls.push(target);
        target = target.nextElementSibling;
      }
      if (target && target.classList.contains("code")) {
        var codeNowHidden = target.classList.toggle("hidden");
        previewEls.forEach(function (el) {
          el.classList.toggle("hidden", !codeNowHidden);
        });
        var label = toggleBtn.querySelector(".code-btn");
        if (label) {
          label.textContent = codeNowHidden ? "Show Code" : "Hide Code";
        }
      }
      return;
    }

    var copyBtn = e.target.closest("[data-copy]");
    if (copyBtn) {
      var codeEl = copyBtn.closest("pre") ? copyBtn.closest("pre").querySelector("code") : null;
      if (codeEl && navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(codeEl.textContent.trim()).then(function () {
          var span = copyBtn.querySelector("span");
          if (span) {
            var original = span.textContent;
            span.textContent = "Copied!";
            setTimeout(function () {
              span.textContent = original;
            }, 1500);
          }
        }).catch(function () {});
      }
      return;
    }

    // UI Kit: Clipboard demo (data-clipboard-action / -target / -text)
    var clipBtn = e.target.closest("[data-clipboard-action]");
    if (clipBtn) {
      var clipAction = clipBtn.getAttribute("data-clipboard-action");
      var clipText = clipBtn.getAttribute("data-clipboard-text");
      var clipTargetSel = clipBtn.getAttribute("data-clipboard-target");
      var clipTargetEl = clipTargetSel ? document.querySelector(clipTargetSel) : null;

      if (clipText == null && clipTargetEl) {
        clipText = ("value" in clipTargetEl) ? clipTargetEl.value : clipTargetEl.textContent.trim();
      }

      if (clipText != null && navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(clipText).then(function () {
          if (clipAction === "cut" && clipTargetEl && "value" in clipTargetEl) {
            clipTargetEl.value = "";
          }
          var clipIcon = clipBtn.querySelector("i");
          if (clipIcon) {
            var clipOriginalClass = clipIcon.className;
            clipIcon.className = clipOriginalClass.replace(/icon-\S+/, "icon-check");
            setTimeout(function () {
              clipIcon.className = clipOriginalClass;
            }, 1200);
          }
        }).catch(function () {});
      }
      return;
    }

    // UI Kit: Collapse component (data-collapse-btn / data-collapse-target)
    var collapseBtn = e.target.closest("[data-collapse-btn], [data-collapse-target]");
    if (collapseBtn) {
      var collapseTargets = [];
      var collapseSelector = collapseBtn.getAttribute("data-collapse-target");
      if (collapseSelector) {
        collapseSelector.split(",").forEach(function (sel) {
          var el = document.querySelector(sel.trim());
          if (el) collapseTargets.push(el);
        });
      } else {
        var collapseWrapper = collapseBtn.closest(".preview-content") || collapseBtn.parentElement;
        var collapseBox = collapseWrapper ? collapseWrapper.querySelector("[data-collapse-box]") : null;
        if (collapseBox) collapseTargets.push(collapseBox);
      }
      collapseTargets.forEach(function (target) {
        var isWidth = target.classList.contains("w-0");
        var prop = isWidth ? "width" : "maxHeight";
        var isOpen = target.dataset.collapseOpen === "true";
        if (isOpen) {
          target.style[prop] = "0px";
          target.dataset.collapseOpen = "false";
        } else {
          target.style[prop] = (isWidth ? target.scrollWidth : target.scrollHeight) + "px";
          target.dataset.collapseOpen = "true";
        }
      });
    }
  });
});

