(function () {
  window.MC = window.MC || {};
  MC.emailSeed = function () {
    return [
      { id: 1, from: "Dr. Alan Reyes", email: "alan.reyes@dreamshms.com", subject: "Patient handover — Ward B", snippet: "Please review the handover notes for bed 12 before your shift.", body: "Hi,\n\nPlease review the handover notes for bed 12 before your shift starts. Vitals have been stable overnight but the attending wants a follow-up chart entry by 9 AM.\n\nThanks,\nDr. Reyes", date: "09:20 AM", folder: "inbox", read: false, starred: true },
      { id: 2, from: "Pharmacy Desk", email: "pharmacy@dreamshms.com", subject: "Low stock alert — Amoxicillin", snippet: "Current stock has dropped below the reorder threshold.", body: "Hello,\n\nAmoxicillin 500mg stock has dropped below the reorder threshold (42 units remaining). Please raise a purchase order at your earliest convenience.\n\nRegards,\nPharmacy Desk", date: "Yesterday", folder: "inbox", read: true, starred: false },
      { id: 3, from: "HR Department", email: "hr@dreamshms.com", subject: "Updated leave policy", snippet: "Please find attached the revised leave policy effective next month.", body: "Dear Team,\n\nPlease find attached the revised leave policy effective next month. Key changes include an additional 2 days of casual leave and a simplified approval workflow.\n\nBest,\nHR Department", date: "2 days ago", folder: "inbox", read: true, starred: true },
      { id: 4, from: "Lab Reports", email: "lab@dreamshms.com", subject: "Results ready — Patient #4821", snippet: "Blood work results are now available for review.", body: "Hi,\n\nBlood work results for patient #4821 are now available for review in the LIS. Please confirm receipt.\n\nThanks,\nLab Team", date: "3 days ago", folder: "inbox", read: false, starred: false },
      { id: 5, from: "Facilities", email: "facilities@dreamshms.com", subject: "Scheduled maintenance — Block A", snippet: "Elevator maintenance is scheduled for this weekend.", body: "Hello,\n\nElevator maintenance in Block A is scheduled for this weekend from 8 AM to 2 PM. Please plan accordingly.\n\nRegards,\nFacilities", date: "5 days ago", folder: "inbox", read: true, starred: false },
      { id: 6, from: "You", email: "me@dreamshms.com", subject: "Re: Discharge summary approval", snippet: "Approved, thanks for the quick turnaround.", body: "Approved, thanks for the quick turnaround.\n\nBest,\nMe", date: "1 week ago", folder: "sent", read: true, starred: false }
    ];
  };
  MC.emailLoad = function () {
    try {
      var raw = localStorage.getItem("hms-email-inbox");
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    var seed = MC.emailSeed();
    localStorage.setItem("hms-email-inbox", JSON.stringify(seed));
    return seed;
  };
  MC.emailSave = function (list) { localStorage.setItem("hms-email-inbox", JSON.stringify(list)); };
})();

document.addEventListener("DOMContentLoaded", function () {
  if (document.body.dataset.page !== "email") return;

  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) { return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; }); };

  var mail = MC.emailLoad();
  var folder = "inbox";

  function initials(name) {
    return (name || "").split(" ").map(function (p) { return p[0]; }).join("").slice(0, 2).toUpperCase();
  }

  function render() {
    var term = $("email-search").value.toLowerCase().trim();
    var rows = mail.filter(function (m) {
      if (folder === "starred") return m.starred;
      if (folder === "trash") return m.folder === "trash";
      if (folder === "sent") return m.folder === "sent";
      return m.folder === "inbox";
    }).filter(function (m) {
      return !term || (m.subject + m.from + m.snippet).toLowerCase().indexOf(term) !== -1;
    });

    $("email-count").textContent = rows.length + " messages";
    $("email-unread-count").textContent = mail.filter(function (m) { return m.folder === "inbox" && !m.read; }).length || "";
    $("email-empty").classList.toggle("hidden", rows.length > 0);

    $("email-list").innerHTML = rows.map(function (m) {
      return '<a href="email-view.html?id=' + m.id + '" class="email-row flex items-start gap-3 p-4 hover:bg-gray-50 dark:hover:bg-slate-700/40 ' + (!m.read ? "bg-blue-50/40 dark:bg-slate-800/60" : "") + '">' +
        '<span class="w-9 h-9 rounded-full bg-primary/10 text-primary flex items-center justify-center text-xs font-bold shrink-0">' + initials(m.from) + '</span>' +
        '<span class="min-w-0 flex-1">' +
        '<span class="flex items-center justify-between gap-2"><span class="text-sm ' + (!m.read ? "font-bold text-gray-900" : "font-medium text-gray-700 dark:text-gray-200") + ' truncate">' + esc(m.from) + '</span><span class="text-xs text-gray-400 shrink-0">' + esc(m.date) + '</span></span>' +
        '<span class="block text-sm ' + (!m.read ? "font-semibold text-gray-900" : "text-gray-600 dark:text-gray-300") + ' truncate">' + esc(m.subject) + '</span>' +
        '<span class="block text-xs text-gray-400 truncate">' + esc(m.snippet) + '</span></span>' +
        '<button type="button" data-id="' + m.id + '" class="email-star-btn shrink-0 p-1 text-lg ' + (m.starred ? "text-amber-400" : "text-gray-300") + '"><i class="icon-star"></i></button>' +
        '</a>';
    }).join("");
  }

  document.querySelectorAll(".email-folder-btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      folder = btn.dataset.folder;
      document.querySelectorAll(".email-folder-btn").forEach(function (b) {
        b.classList.remove("bg-primary/10", "text-primary", "font-semibold");
        b.classList.add("text-gray-600", "dark:text-gray-300", "font-medium");
      });
      btn.classList.add("bg-primary/10", "text-primary", "font-semibold");
      btn.classList.remove("text-gray-600", "dark:text-gray-300", "font-medium");
      render();
    });
  });

  $("email-list").addEventListener("click", function (e) {
    var star = e.target.closest(".email-star-btn");
    if (!star) return;
    e.preventDefault();
    var id = parseInt(star.dataset.id, 10);
    mail = mail.map(function (m) { return m.id === id ? Object.assign({}, m, { starred: !m.starred }) : m; });
    MC.emailSave(mail);
    render();
  });

  $("email-search").addEventListener("input", render);
  render();
});





