            (function () {
                "use strict";

                if (typeof Quill === "undefined") return;

                const FULL_TOOLBAR = [
                    [{ header: [1, 2, 3, false] }],
                    ["bold", "italic", "underline", "strike"],
                    [{ color: [] }, { background: [] }],
                    [{ list: "ordered" }, { list: "bullet" }],
                    [{ align: [] }],
                    ["blockquote", "code-block"],
                    ["link", "image"],
                    ["clean"],
                ];

                const SIMPLE_TOOLBAR = [
                    ["bold", "italic", "underline"],
                    [{ list: "ordered" }, { list: "bullet" }],
                    ["link", "clean"],
                ];

                function init(selector, options) {
                    if (!document.querySelector(selector)) return null;
                    return new Quill(selector, options);
                }

                init("#editor-snow", {
                    theme: "snow",
                    placeholder: "Write the discharge summary...",
                    modules: { toolbar: FULL_TOOLBAR },
                });

                init("#editor-simple", {
                    theme: "snow",
                    placeholder: "Add a short clinical note...",
                    modules: { toolbar: SIMPLE_TOOLBAR },
                });

                init("#editor-bubble", {
                    theme: "bubble",
                    placeholder: "Select text to format it...",
                });

                init("#editor-readonly", {
                    theme: "snow",
                    readOnly: true,
                    modules: { toolbar: false },
                });

                init("#editor-form", {
                    theme: "snow",
                    placeholder: "Compose the template body...",
                    modules: { toolbar: SIMPLE_TOOLBAR },
                });
            })();

