            // Flatpickr instances are initialised globally from assets/js/script.js via the
            // [data-provider="flatpickr"] / [data-provider="timepickr"] attributes.
            (function () {
                "use strict";

                // Keep the colour swatch input and its hex field in sync.
                const picker = document.getElementById("fp-color");
                const hex = picker && picker.parentElement.querySelector('input[type="text"]');
                if (!picker || !hex) return;

                picker.addEventListener("input", function () {
                    hex.value = picker.value;
                });

                hex.addEventListener("change", function () {
                    if (/^#[0-9a-f]{6}$/i.test(hex.value)) picker.value = hex.value;
                });
            })();

