                                $("#ad-occwidget").innerHTML = occ.map(function (o) { return '<div class="ad-c-' + o[2] + '"><div class="flex justify-between text-xs mb-1"><span class="text-gray-500 dark:text-gray-400">' + o[0] + '</span><b class="text-gray-900 dark:text-white">' + o[1] + '%</b></div><div class="ad-bar"><i style="width:' + o[1] + '%"></i></div></div>'; }).join("");

                                var dept = [["Cardiology", 24, "rose"], ["ICU", 18, "violet"], ["Maternity", 15, "teal"]];
                                $("#ad-deptwidget").innerHTML = dept.map(function (d) { return '<div class="ad-c-' + d[2] + '"><div class="flex justify-between text-xs mb-1"><span class="text-gray-500 dark:text-gray-400">' + d[0] + '</span><b class="text-gray-900 dark:text-white">' + d[1] + '</b></div><div class="ad-bar"><i style="width:' + d[1] * 3 + '%"></i></div></div>'; }).join("");

                                $("#ad-recentwidget").innerHTML = data.slice(0, 6).map(function (r) { return '<button class="ad-recent w-full text-left ad-view" data-id="' + r.id + '"><span class="' + acc(r.dept) + ' ad-ava-ring" style="border-radius:.7rem"><img class="ad-ava object-cover" style="width:2.1rem;height:2.1rem;border-radius:.6rem" src="' + photo(r.id) + '" alt=""></span><div class="min-w-0 flex-1"><p class="text-xs font-bold text-gray-900 dark:text-white truncate">' + esc(r.name) + '</p><p class="text-[10px] text-gray-400">' + aid(r.id) + ' · ' + r.ward + '</p></div>' + statusBadge(r.status) + '</button>'; }).join("");

