                function bubXY(count,xmax,ymax,zmin,zmax){ const out=[]; for(let i=0;i<count;i++){ out.push({x:Math.round(rnd(0,xmax)),y:Math.round(rnd(0,ymax)),z:Math.round(rnd(zmin,zmax))}); } return out; }

