                                    sec("Follow-up Schedule", '<div class="dc-recent" style="border:1px solid var(--color-border-color)"><span class="dc-clear-ico dc-c-violet"><i class="icon-calendar-clock"></i></span><div class="flex-1"><p class="text-xs font-bold text-gray-900 dark:text-white">Cardiology Review</p><p class="text-[10px] text-gray-400">' + (r.fu ? r.followUp : "Not scheduled") + ' · ' + esc(r.doctor) + '</p></div></div>') +
                                    sec("Billing Status", '<div class="flex items-center gap-2"><div class="dc-bar dc-c-emerald flex-1"><i style="width:100%"></i></div><span class="dc-chip dc-c-emerald">Cleared</span></div>') +
                                    sec("Timeline", '<div class="dc-tl ' + acc(r.dept) + '">' + tl("Admitted", r.admit, "icon-log-in") + tl("Treatment completed", r.discharge, "icon-activity") + tl("Doctor approval · " + esc(r.doctor), r.discharge, "icon-stethoscope") + tl("Clearances processed", r.discharge, "icon-clipboard-check") + tl("Discharged", r.discharge, "icon-log-out") + '</div>') +
                                    '<div class="grid grid-cols-2 gap-2"><button class="dc-btn dc-btn-success" data-da="approve" data-id="' + id + '"><i class="icon-badge-check"></i>Approve</button><button class="dc-btn dc-btn-primary" data-da="followup" data-id="' + id + '"><i class="icon-calendar-plus"></i>Follow-up</button><button class="dc-btn dc-btn-solid" data-da="print" data-id="' + id + '"><i class="icon-printer"></i>Summary</button><button class="dc-btn dc-btn-solid" data-da="email" data-id="' + id + '"><i class="icon-mail"></i>Email</button></div></div>';
