                                var ed = e.target.closest(".dc-edit"); if (ed) return rowAction("edit", +ed.getAttribute("data-id"));
                                var ch = e.target.closest(".dc-rowcheck"); if (ch) { if (ch.checked) state.sel[+ch.getAttribute("data-id")] = true; else delete state.sel[+ch.getAttribute("data-id")]; return render(); }
                                if (e.target.closest("a,button,input")) return;
