(function () {
    "use strict";
    if (document.body.dataset.page !== "emergency") return;

    const pad = (n) => "#ER-" + String(n).padStart(4, "0");
    const detailUrl = (r) => "emergency-detail.html?" + new URLSearchParams({ id: r.id, patient: r.patient, complaint: r.complaint, triage: r.triage, status: r.status }).toString();
    const TBADGE = {
        "Red (Critical)": "text-danger bg-danger/10",
        "Orange (Urgent)": "text-warning bg-warning/10",
        "Yellow (Semi-urgent)": "text-info bg-info/10",
        "Green (Non-urgent)": "text-success bg-success/10",
    };
    const SBADGE = {
        Waiting: "text-warning bg-warning/10",
        "In Treatment": "text-primary bg-primary/10",
        Admitted: "text-purple bg-purple/10",
        Discharged: "text-success bg-success/10",
    };
    const now = () => {
        const d = new Date();
        return d.toISOString().slice(0, 16);
    };
    const data = [
        { id: 1, patient: "Carlos Vega", agegen: "52/M", complaint: "Severe chest pain, sweating", triage: "Red (Critical)", doctor: "Dr. Tom Rivas", arrival: "2024-12-10T08:15", status: "In Treatment", notes: "Suspected MI" },
        { id: 2, patient: "Diana Park", agegen: "34/F", complaint: "Difficulty breathing, high fever", triage: "Orange (Urgent)", doctor: "Dr. Sarah Chen", arrival: "2024-12-10T09:00", status: "In Treatment", notes: "" },
        { id: 3, patient: "Brian Lee", agegen: "28/M", complaint: "Deep laceration on forearm", triage: "Yellow (Semi-urgent)", doctor: "Dr. Alice Mills", arrival: "2024-12-10T09:30", status: "Waiting", notes: "" },
        { id: 4, patient: "Sophie Turner", agegen: "19/F", complaint: "Allergic reaction, hives", triage: "Orange (Urgent)", doctor: "Dr. James Park", arrival: "2024-12-10T10:00", status: "Admitted", notes: "Anaphylaxis — epinephrine given" },
        { id: 5, patient: "Mark Davis", agegen: "67/M", complaint: "Fall, suspected hip fracture", triage: "Orange (Urgent)", doctor: "Dr. Felix Osei", arrival: "2024-12-10T10:45", status: "Waiting", notes: "" },
        { id: 6, patient: "Aisha Kofi", agegen: "8/F", complaint: "High fever, seizure", triage: "Red (Critical)", doctor: "Dr. James Park", arrival: "2024-12-10T11:00", status: "In Treatment", notes: "Febrile seizure — pediatric emergency" },
        { id: 7, patient: "Peter Walsh", agegen: "45/M", complaint: "Minor burn on hand", triage: "Green (Non-urgent)", doctor: "Dr. Tom Rivas", arrival: "2024-12-10T11:30", status: "Discharged", notes: "" },
        { id: 8, patient: "Hannah Cruz", agegen: "38/F", complaint: "Abdominal pain", triage: "Yellow (Semi-urgent)", doctor: "Dr. Li Wang", arrival: "2024-12-10T12:00", status: "Waiting", notes: "" },
    ];
    function rowHTML(r) {
        return `<tr data-row-id="${r.id}"><td class="text-primary font-mono text-sm"><a href="${detailUrl(r)}">${pad(r.id)}</a></td><td><p class="font-medium text-gray-900">${r.patient}</p><p class="text-xs text-gray-400">${r.agegen}</p></td><td class="text-gray-600 dark:text-gray-300 max-w-xs">${r.complaint}</td><td><span class="inline-block px-2 py-1 text-xs font-semibold rounded-lg whitespace-nowrap ${TBADGE[r.triage] || "text-gray-900 bg-light/60"} text-xs">${r.triage}</span></td><td class="text-gray-500 dark:text-gray-400 text-sm">${r.doctor}</td><td class="text-gray-500 dark:text-gray-400 text-sm">${r.arrival.replace("T", " ")}</td><td><span class="inline-block px-2 py-1 text-xs font-semibold rounded-lg whitespace-nowrap ${SBADGE[r.status] || "text-gray-900 bg-light/60"}">${r.status}</span></td><td><div class="flex gap-1"><button data-hs-overlay="#form-modal" onclick="emergencyOpenEdit(${r.id})" class="p-1.5 size-7 flex items-center justify-center rounded-lg hover:bg-gray-100 dark:hover:bg-slate-700 text-gray-500 dark:text-gray-400" title="Edit"><i class="icon-edit text-base"></i></button><button data-hs-overlay="#del-modal" onclick="emergencyDeleteRecord(${r.id},'${r.patient}')" class="p-1.5 size-7 flex items-center justify-center rounded hover:bg-danger/20 dark:hover:bg-red-900/20 text-danger" title="Close"><i class="icon-trash-2 text-base"></i></button></div></td></tr>`;
    }

    document.addEventListener("DOMContentLoaded", () => {
        MC.crudList({
            prefix: "emergency", deleteFnName: "emergencyDeleteRecord", data: data, nextId: 9, rowHTML: rowHTML,
            searchFields: ["patient", "complaint"],
            filters: [{ id: "filter-triage", field: "triage" }, { id: "filter-status", field: "status" }],
            addTitle: "Register Emergency Case", addSaveLabel: "Register", editTitle: "Edit Case",
            addToast: "Emergency case registered", editToast: "Case updated", deleteToast: "Case closed",
            onOpenAdd: ($) => { $("f-arrival").value = now(); },
            updateStats: (_$, data) => {
                document.getElementById("stat-total").textContent = data.filter((r) => r.status !== "Discharged").length;
                document.getElementById("stat-critical").textContent = data.filter((r) => r.triage === "Red (Critical)" && r.status !== "Discharged").length;
                document.getElementById("stat-urgent").textContent = data.filter((r) => r.triage === "Orange (Urgent)" && r.status !== "Discharged").length;
                document.getElementById("stat-stable").textContent = data.filter((r) => ["Green (Non-urgent)", "Yellow (Semi-urgent)"].includes(r.triage) || r.status === "Discharged").length;
            },
            fillForm: (_$, r) => {
                document.getElementById("f-patient").value = r.patient;
                document.getElementById("f-agegen").value = r.agegen;
                document.getElementById("f-complaint").value = r.complaint;
                document.getElementById("f-triage").value = r.triage;
                document.getElementById("f-doctor").value = r.doctor;
                document.getElementById("f-arrival").value = r.arrival;
                document.getElementById("f-status").value = r.status;
                document.getElementById("f-notes").value = r.notes;
            },
            buildRecord: () => {
                const patient = document.getElementById("f-patient").value.trim();
                const complaint = document.getElementById("f-complaint").value.trim();
                if (!patient) { MC.toast("Patient name required", "error"); return null; }
                if (!complaint) { MC.toast("Complaint required", "error"); return null; }
                return {
                    patient,
                    agegen: document.getElementById("f-agegen").value.trim(),
                    complaint,
                    triage: document.getElementById("f-triage").value,
                    doctor: document.getElementById("f-doctor").value.trim(),
                    arrival: document.getElementById("f-arrival").value,
                    status: document.getElementById("f-status").value,
                    notes: document.getElementById("f-notes").value.trim(),
                };
            },
        });
    });
})();

