                                var status = [["Confirmed", by(function (r) { return r.status === "Confirmed"; }), "emerald"], ["Pending", by(function (r) { return r.status === "Pending"; }), "amber"], ["Completed", by(function (r) { return r.status === "Completed"; }), "primary"], ["Cancelled", by(function (r) { return r.status === "Cancelled"; }), "rose"]];
