                            function importModal() { modal({ title: "Import Visits", sub: "CSV or Excel", icon: "icon-upload", accent: "pv-c-sky", confirm: "Import", body: '<div style="border:2px dashed var(--color-border-color);border-radius:.9rem;padding:1.75rem;text-align:center;color:var(--color-gray-500)"><i class="icon-cloud-upload text-3xl"></i><p class="text-sm font-bold mt-1">Drag &amp; drop your file</p><p class="text-[11px]">CSV, XLSX up to 10MB</p></div><div class="flex items-center gap-2 mt-3"><span class="pv-chip pv-c-emerald">CSV</span><span class="pv-chip pv-c-emerald">Excel</span><a href="#" class="ml-auto text-xs font-bold text-primary hover:underline" id="pv-tmpl">Download template</a></div><div class="mt-3 rounded-xl border border-border-color p-3 grid grid-cols-3 text-center"><div><p class="text-lg font-extrabold text-emerald-600">20</p><p class="text-[10px] text-gray-500">Valid</p></div><div><p class="text-lg font-extrabold text-amber-600">2</p><p class="text-[10px] text-gray-500">Warnings</p></div><div><p class="text-lg font-extrabold text-rose-600">0</p><p class="text-[10px] text-gray-500">Errors</p></div></div>', onConfirm: function () { toast("Imported 20 visits (2 warnings)"); } }); var tm = $("#pv-tmpl"); if (tm) tm.onclick = function (e) { e.preventDefault(); toast("Template downloaded", "info"); }; }
