                                    body: '<label class="pv-lbl">Format</label><div class="grid grid-cols-4 gap-2 mb-3">' + ["CSV", "Excel", "PDF", "Print"].map(function (f, i) { return '<label class="flex items-center justify-center gap-1 rounded-lg border border-border-color p-2 cursor-pointer text-xs font-bold text-gray-700 dark:text-gray-300"><input type="radio" name="pv-exf" value="' + f + '"' + (i === 0 ? " checked" : "") + " class=\"accent-primary\">" + f + "</label>"; }).join("") + '</div><label class="pv-lbl">Records</label><div class="space-y-2">' + [["all", "All records"], ["filtered", "Current filters"], ["selected", "Selected (" + selN() + ")"]].map(function (o, i) { return '<label class="flex items-center gap-2.5 rounded-xl border border-border-color p-2.5 cursor-pointer text-sm text-gray-700 dark:text-gray-300"><input type="radio" name="pv-exs" value="' + o[0] + '"' + (i === 0 ? " checked" : "") + ' class="accent-primary">' + o[1] + "</label>"; }).join("") + "</div>",
                                    onConfirm: function () { var f = (document.querySelector('input[name="pv-exf"]:checked') || {}).value || "CSV"; var s = (document.querySelector('input[name="pv-exs"]:checked') || {}).value || "all"; if (f === "Print") { toast("Opening print…", "info"); setTimeout(function () { window.print(); }, 400); } else toast("Exported " + s + " as " + f); }
