                        sec("Interpretation", '<p class="text-sm text-gray-600 dark:text-gray-300">' + (r.status === "Normal" ? "Within normal limits. Continue routine monitoring." : r.status === "High" ? "Above the normal threshold. Monitor closely and review medication." : r.status === "Low" ? "Below the normal threshold. Assess patient and reassess shortly." : "Critical value — notify the attending physician immediately.") + '</p>') +
                        '<div class="grid grid-cols-2 gap-2"><button class="vit-btn vit-btn-primary" data-da="notify" data-id="' + id + '"><i class="icon-mail"></i>Notify Doctor</button><button class="vit-btn vit-btn-success" data-da="flag" data-id="' + id + '"><i class="icon-flag"></i>Annotate</button><button class="vit-btn vit-btn-solid" data-da="edit" data-id="' + id + '"><i class="icon-edit"></i>Edit</button><button class="vit-btn vit-btn-solid" data-da="download" data-id="' + id + '"><i class="icon-download"></i>Download</button></div></div>';
                    $("#vit-detail-drawer").classList.add("open");
