                /* ---- bulk ---- */
                function bulk(a) {
                    var recs = selectedRecs(), n = recs.length;
                    if (!n && a !== "clear") return toast("No readings selected", "error");
                    switch (a) {
                        case "clear": state.sel = {}; render(); return;
                        case "export": return toast("Exported " + n + " readings");
                        case "print": toast("Printing " + n + " readings…", "info"); return setTimeout(function () { window.print(); }, 400);
                        case "flag": return toast(n + " readings flagged for review");
                        case "delete": return modal({ title: "Delete " + n + " readings", sub: "This cannot be undone", icon: "icon-trash-2", accent: "vit-c-rose", danger: true, confirm: "Delete " + n, body: '<p class="text-sm text-gray-600 dark:text-gray-300">Delete ' + n + " selected readings?</p>", onConfirm: function () { data = data.filter(function (x) { return !state.sel[x.id]; }); state.sel = {}; render(); toast(n + " readings deleted"); } });
                    }
                }

                setTimeout(function () {
                    var sk = $("#vit-skeleton"), ct = $("#vit-content");
                    if (sk) sk.style.display = "none";
                    if (ct) { ct.classList.remove("hidden"); ct.style.animation = "vit-fadein .4s ease"; }
                    render(true);
                }, 1500);

                function on(id, ev, fn) { var el = $("#" + id); if (el) el.addEventListener(ev, fn); }
                on("vit-search", "input", function (e) { state.q = e.target.value; state.page = 1; render(); });
                on("vit-f-param", "change", function (e) { state.param = e.target.value; state.page = 1; render(); });
                on("vit-f-status", "change", function (e) { state.status = e.target.value; state.page = 1; render(); });
                on("vit-sort", "change", function (e) { state.sort = e.target.value; render(); });
                on("vit-view-list", "click", function () { state.view = "list"; this.classList.add("is-active"); $("#vit-view-grid").classList.remove("is-active"); render(); });
                on("vit-view-grid", "click", function () { state.view = "grid"; this.classList.add("is-active"); $("#vit-view-list").classList.remove("is-active"); render(); });
                on("vit-refresh", "click", function () { toast("Refreshed"); $("#vit-updated").textContent = "just now"; buildDashboard(); render(); });
                on("vit-import", "click", importModal);
                on("vit-export", "click", exportModal);
                on("vit-print", "click", function () { toast("Printing vitals report…", "info"); setTimeout(function () { window.print(); }, 400); });
                on("vit-filters", "click", function () { $("#vit-filter-drawer").classList.add("open"); document.body.style.overflow = "hidden"; });
                on("vit-size", "change", function (e) { state.size = +e.target.value; state.page = 1; render(); });
                on("vit-jump", "change", function (e) { var v = +e.target.value; if (v >= 1) { state.page = v; render(); } });
