                $("#vit-page-nav").addEventListener("click", function (e) { var b = e.target.closest("[data-pg]"); if (!b) return; var v = b.getAttribute("data-pg"); if (v === "prev") state.page--; else if (v === "next") state.page++; else state.page = +v; render(); });

                function selectAll(e) { var onn = e.target.checked, start = (state.page - 1) * state.size, rows = filtered().slice(start, start + state.size); rows.forEach(function (r) { if (onn) state.sel[r.id] = true; else delete state.sel[r.id]; }); render(); }
                on("vit-select-all", "change", selectAll); on("vit-select-all-2", "change", selectAll);

                function delegate(e) {
                    var mb = e.target.closest(".vit-menu-btn"); if (mb) { e.stopPropagation(); return showMenu(mb, +mb.getAttribute("data-id")); }
                    var v = e.target.closest(".vit-view"); if (v) return openDetail(+v.getAttribute("data-id"));
                    var ed = e.target.closest(".vit-edit"); if (ed) return rowAction("edit", +ed.getAttribute("data-id"));
                    var ch = e.target.closest(".vit-rowcheck"); if (ch) { if (ch.checked) state.sel[+ch.getAttribute("data-id")] = true; else delete state.sel[+ch.getAttribute("data-id")]; return render(); }
                    if (e.target.closest("a,button,input")) return;
                    var card = e.target.closest(".vit-card[data-id]"); if (card) return openDetail(+card.getAttribute("data-id"));
                    var row = e.target.closest("tr[data-id]"); if (row) return openDetail(+row.getAttribute("data-id"));
                }
                listView.addEventListener("click", delegate); grid.addEventListener("click", delegate);

                page.addEventListener("click", function (e) {
                    var v = e.target.closest("#vit-recentwidget .vit-view"); if (v) return openDetail(+v.getAttribute("data-id"));
                });

                document.addEventListener("click", function (e) {
                    var op = e.target.closest("[data-open]"); if (op) { var k = op.getAttribute("data-open"); if (k === "record") return recordModal(); if (k === "device") return deviceModal(); if (k === "alerts") return alertsModal(); if (k === "export") return exportModal(); }
                    if (e.target.closest("[data-close]")) { closeModal(); $$(".vit-drawer.open").forEach(function (dr) { dr.classList.remove("open"); }); }
                    var da = e.target.closest("[data-da]"); if (da) { $("#vit-detail-drawer").classList.remove("open"); document.body.style.overflow = ""; rowAction(da.getAttribute("data-da"), +da.getAttribute("data-id")); }
                    if (menu && !menu.contains(e.target) && !e.target.closest(".vit-menu-btn")) closeMenu();
                });
                $("#vit-modal").addEventListener("mousedown", function (e) { if (e.target === this || e.target.classList.contains("vit-modal-back")) closeModal(); });
                $("#vit-bulkbar").addEventListener("click", function (e) { var b = e.target.closest("[data-bulk]"); if (b) bulk(b.getAttribute("data-bulk")); });
                window.addEventListener("resize", closeMenu);
