                const defaultGrant=(m,r)=>{ if(r==='Admin')return 1; const map={Patients:['Doctor','Nurse','Reception'],Appointments:['Doctor','Nurse','Reception'],Billing:['Billing','Reception'],Pharmacy:['Pharmacy','Doctor'],Laboratory:['Lab','Doctor'],Reports:['Doctor','HR','Billing'],Settings:[]}; return (map[m]||[]).includes(r)?1:0; };
                let GRANTS={}; MODS.forEach(m=>{GRANTS[m]={}; ROLES.forEach(r=>GRANTS[m][r]=defaultGrant(m,r));});
