                const PERF=[['Cache','ti-bolt',68,'#6366f1','Redis · 68%'],['Database','ti-database','OK','#22c55e','12ms avg'],['CPU Usage','ti-cpu',34,'#0ea5e9','4 cores'],['Memory','ti-server',57,'#f59e0b','9.1/16 GB'],['Storage','fa-solid fa-hard-drive',41,'#a855f7','418 GB'],['Queue Jobs','ti-list-check',12,'#06b6d4','12 pending'],['Log Size','ti-file-stack',22,'#ec4899','220 MB'],['Uptime','ti-activity','99.9%','#10b981','30 days']];
